function GetVendorDetail(produrl){if(produrl.indexOf('koovs')>-1){return'koovs|1';}
if(produrl.indexOf('jabong')>-1){return'jabong|2';}
if(produrl.indexOf('americanwan')>-1){return'americanwan|3';}
if(produrl.indexOf('zovi')>-1){return'zovi|4';}
if(produrl.indexOf('shopnineteen')>-1){return'shopnineteen|5';}
if(produrl.indexOf('flipkart')>-1){return'flipkart|6';}
if(produrl.indexOf('zivame')>-1){return'zivame|7';}
if(produrl.indexOf('myntra')>-1){return'myntra|8';}
if(produrl.indexOf('trendin')>-1){return'trendin|10';}
if(produrl.indexOf('fabfurnish')>-1){return'fabfurnish|12';}
if(produrl.indexOf('homeshop18')>-1){return'homeshop18|13';}}
